insert into public.formula_cards (
  id, chapter_id, title, card_type, body, formulas, variables, conditions, table_data, diagram_data, diagram_svg, recall_data, importance, source_page, sort_order, is_active
)
values
  ('neet-biology-breathing-and-exchange-of-gases-respiration-vs-breathing', 'neet-biology-breathing-and-exchange-of-gases', 'Respiration vs Breathing', 'comparison', 'Respiration releases energy by oxidation of nutrients in living cells; breathing exchanges atmospheric O2 with cellular CO2.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Term","Recall answer"],"rows":[["Respiration","Oxidation of nutrients in living cells to release energy for biological work."],["Breathing","Exchange of O2 from atmosphere with CO2 produced by cells."]]}'::jsonb, null, null, '{"recall_question":"Which process releases energy by oxidation of nutrients?","reveal_answer":"Respiration.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 4, 69, 1, true),
  ('neet-biology-breathing-and-exchange-of-gases-respiratory-organs', 'neet-biology-breathing-and-exchange-of-gases', 'Respiratory Organs Across Animals', 'examples', 'The source links respiratory organs to animal groups.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Respiratory surface","Source examples"],"rows":[["General body surface","Sponges, coelenterates, flatworms etc."],["Skin/moist cuticle","Earthworms, leech, amphibians etc."],["Tracheal tubes","Insects, centipede, millipede, spider."],["Gills","Fishes, tadpoles, prawn."],["Lungs","Most vertebrates."]]}'::jsonb, null, null, '{"recall_question":"Which respiratory organ is listed for insects?","reveal_answer":"Tracheal tubes.","key_points":["Centipede, millipede and spider are also listed with tracheal tubes."],"examples":[],"neet_traps":[]}'::jsonb, 4, 69, 2, true),
  ('neet-biology-breathing-and-exchange-of-gases-respiratory-pathway', 'neet-biology-breathing-and-exchange-of-gases', 'Human Respiratory Pathway', 'sequence', 'Air moves through the conducting part before reaching the exchange region.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Order","Part"],"rows":[["1","External nostrils"],["2","Nasal passage and nasal chamber"],["3","Pharynx"],["4","Glottis and larynx"],["5","Trachea"],["6","Primary, secondary and tertiary bronchi"],["7","Bronchioles and terminal bronchioles"],["8","Respiratory bronchiole and alveolar duct"]]}'::jsonb, '{"type":"bio-respiratory-pathway"}'::jsonb, null, '{"recall_question":"What comes after trachea in the source pathway?","reveal_answer":"Primary bronchi.","key_points":["The pathway continues to secondary bronchi, tertiary bronchi, bronchioles, terminal bronchioles, respiratory bronchiole and alveolar duct."],"examples":[],"neet_traps":[]}'::jsonb, 5, 69, 3, true),
  ('neet-biology-breathing-and-exchange-of-gases-conducting-and-exchange-parts', 'neet-biology-breathing-and-exchange-of-gases', 'Conducting Part vs Exchange Part', 'comparison', 'The source separates air transport from gas exchange.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Part","Source-backed role"],"rows":[["Conducting part","Transports atmospheric air into alveoli, clears foreign particles, humidifies air and brings air to body temperature."],["Respiratory/exchange part","Alveoli and ducts where gas exchange occurs."],["Alveoli","Structural and functional units of lungs."]]}'::jsonb, null, null, '{"recall_question":"What are the structural and functional units of lungs?","reveal_answer":"Alveoli.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 69, 4, true),
  ('neet-biology-breathing-and-exchange-of-gases-larynx-epiglottis-pleura', 'neet-biology-breathing-and-exchange-of-gases', 'Larynx, Epiglottis and Pleura', 'fact', 'Small anatomy details are repeatedly tested.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Structure","Recall detail"],"rows":[["Larynx","Sound box or voice box; helps sound production."],["Epiglottis","Closes the glottis to prevent entry of food into the larynx."],["Trachea/bronchi/initial bronchioles","Supported by incomplete cartilaginous half rings."],["Pleura","Double layer: outer parietal and inner visceral; pleural fluid prevents friction."],["Lungs","Right lung has 3 lobes and left lung has 2 lobes."]]}'::jsonb, null, null, '{"recall_question":"Which lung has 3 lobes in the source?","reveal_answer":"Right lung.","key_points":[],"examples":[],"neet_traps":["Left lung has 2 lobes."]}'::jsonb, 4, 69, 5, true),
  ('neet-biology-breathing-and-exchange-of-gases-steps-of-respiration', 'neet-biology-breathing-and-exchange-of-gases', 'Five Steps of Respiration', 'sequence', 'The source gives respiration as a five-step flow from ventilation to cellular respiration.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Step","Process"],"rows":[["1","Pulmonary ventilation or breathing"],["2","Gas exchange between lung alveoli and blood"],["3","Transport of O2 and CO2 by blood"],["4","Gas exchange between blood and tissues"],["5","Cellular or tissue respiration"]]}'::jsonb, null, null, '{"recall_question":"What is the first step of respiration in the source?","reveal_answer":"Pulmonary ventilation or breathing.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 4, 69, 6, true),
  ('neet-biology-breathing-and-exchange-of-gases-inspiration-vs-expiration', 'neet-biology-breathing-and-exchange-of-gases', 'Inspiration vs Expiration', 'comparison', 'Breathing depends on thoracic volume and pulmonary pressure changes.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Feature","Inspiration","Expiration"],"rows":[["Nature","Active intake of air","Passive expelling of air"],["Diaphragm","Contracts and flattens","Relaxes"],["External intercostals","Lift ribs and sternum","Relax"],["Thoracic volume","Increases","Decreases"],["Intra-pulmonary pressure","Falls below atmospheric pressure","Rises above atmospheric pressure"],["Forceful expiration","-","Abdominal and internal inter-costal muscles contract"]]}'::jsonb, '{"type":"bio-breathing-mechanics"}'::jsonb, null, '{"recall_question":"Why does air enter during inspiration?","reveal_answer":"Intra-pulmonary pressure falls below atmospheric pressure.","key_points":["Diaphragm contraction and rib movement increase thoracic and pulmonary volume."],"examples":[],"neet_traps":[]}'::jsonb, 5, 70, 7, true),
  ('neet-biology-breathing-and-exchange-of-gases-respiratory-volumes', 'neet-biology-breathing-and-exchange-of-gases', 'Respiratory Volumes', 'fact', 'Use the handbook values exactly for NEET recall.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Volume","Definition","Source value"],"rows":[["TV","Air inspired or expired during normal respiration","About 500 ml; 6000-8000 ml per minute"],["IRV","Additional air inspired by forceful inspiration","2500-3000 ml"],["ERV","Additional air expired by forceful expiration","1000-1100 ml"],["RV","Air remaining after forcible expiration","1100-1200 ml"],["Dead space","Respiratory tract from nostrils to terminal bronchi not involved in gas exchange","About 150 ml"]]}'::jsonb, null, null, '{"recall_question":"What is tidal volume according to the source?","reveal_answer":"About 500 ml.","key_points":["The source also states 6000-8000 ml per minute."],"examples":[],"neet_traps":[]}'::jsonb, 5, 70, 8, true),
  ('neet-biology-breathing-and-exchange-of-gases-respiratory-capacities', 'neet-biology-breathing-and-exchange-of-gases', 'Respiratory Capacities', 'fact', 'Capacities combine respiratory volumes.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Capacity","Formula or definition","Source value"],"rows":[["IC","TV + IRV; total air inspired after normal expiration","3000-3500 ml"],["EC","TV + ERV; total air expired after normal inspiration","1500-1600 ml"],["FRC","ERV + RV; air remaining after normal expiration","2100-2300 ml"],["VC","ERV + TV + IRV; air breathed in after forced expiration or out after forced inspiration","3500-4500 ml"],["TLC","RV + ERV + TV + IRV or VC + RV","5000-6000 ml"]]}'::jsonb, null, null, '{"recall_question":"Which capacity equals ERV + RV?","reveal_answer":"Functional residual capacity (FRC).","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 70, 9, true),
  ('neet-biology-breathing-and-exchange-of-gases-respiratory-rate-cycle', 'neet-biology-breathing-and-exchange-of-gases', 'Respiratory Cycle and Rate', 'fact', 'A respiratory cycle is an inspiration plus expiration.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Recall cue","Source value"],"rows":[["Respiratory cycle","One inspiration + one expiration"],["Normal respiratory rate","12-16 times/min"],["Instrument","Spirometer or respirometer measures respiratory rate"]]}'::jsonb, null, null, '{"recall_question":"What is one respiratory cycle?","reveal_answer":"An inspiration and an expiration.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 4, 70, 10, true),
  ('neet-biology-breathing-and-exchange-of-gases-partial-pressure-table', 'neet-biology-breathing-and-exchange-of-gases', 'Partial Pressures in Gas Exchange', 'table', 'O2 and CO2 diffuse according to partial-pressure gradients.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Site","pO2 (mm Hg)","pCO2 (mm Hg)"],"rows":[["Atmospheric air","159","0.3"],["Alveoli","104","40"],["Deoxygenated blood","40","45"],["Oxygenated blood","95","40"],["Tissues","40","45"]]}'::jsonb, '{"type":"bio-alveolus-exchange"}'::jsonb, null, '{"recall_question":"Why does O2 diffuse from alveoli into blood?","reveal_answer":"Alveolar pO2 is 104 mm Hg while deoxygenated blood pO2 is 40 mm Hg.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 70, 11, true),
  ('neet-biology-breathing-and-exchange-of-gases-diffusion-membrane', 'neet-biology-breathing-and-exchange-of-gases', 'Diffusion Membrane', 'fact', 'Gas exchange depends on gradient, solubility, membrane thickness and surface area.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Layer/factor","Source-backed recall"],"rows":[["Layer 1","Squamous epithelium of alveoli"],["Layer 2","Endothelium of alveolar capillaries"],["Layer 3","Basement substance"],["Thickness","0.5 µm"],["CO2 solubility","20-25 times higher than O2"]]}'::jsonb, null, null, '{"recall_question":"Why does CO2 diffuse efficiently despite a small pressure difference?","reveal_answer":"CO2 solubility is 20-25 times higher than O2.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 70, 12, true),
  ('neet-biology-breathing-and-exchange-of-gases-oxygen-transport', 'neet-biology-breathing-and-exchange-of-gases', 'Oxygen Transport', 'concept', 'Most oxygen is transported by haemoglobin as oxyhaemoglobin.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Mode/factor","Source-backed detail"],"rows":[["Dissolved in plasma","3%"],["By haemoglobin","97% as oxyhaemoglobin"],["Hb capacity","Each Hb has 4 haem units and carries 4 O2 molecules"],["Alveoli favour binding","High pO2, low pCO2, lesser H+ and lower temperature"],["Tissues favour release","Low pO2, high pCO2, high H+ and high temperature"],["Delivery","Every 100 ml oxygenated blood delivers around 5 ml O2 to tissues"]]}'::jsonb, '{"type":"bio-oxygen-dissociation"}'::jsonb, null, '{"recall_question":"How much O2 is transported by haemoglobin?","reveal_answer":"97%.","key_points":["It is transported as oxyhaemoglobin."],"examples":[],"neet_traps":[]}'::jsonb, 5, 70, 13, true),
  ('neet-biology-breathing-and-exchange-of-gases-carbon-dioxide-transport', 'neet-biology-breathing-and-exchange-of-gases', 'Carbon Dioxide Transport', 'concept', 'CO2 moves mainly as bicarbonates; carbonic anhydrase is abundant in RBCs.', '[{"label":"CO2 conversion","latex":"CO_2 + H_2O \\rightleftharpoons H_2CO_3 \\rightleftharpoons HCO_3^- + H^+"}]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Mode","Source-backed share/detail"],"rows":[["Carbonic acid","7% as CO2 dissolved in plasma water to form carbonic acid"],["Carbamino-haemoglobin","20-25% bound with haemoglobin"],["Bicarbonates","70%"],["Carbonic anhydrase","Present in RBCs and in very small quantity in plasma"],["Delivery","Every 100 ml deoxygenated blood delivers about 4 ml CO2 to alveoli"]]}'::jsonb, null, null, '{"recall_question":"What is the main transport form of CO2 in the source?","reveal_answer":"Bicarbonates, about 70%.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 71, 14, true),
  ('neet-biology-breathing-and-exchange-of-gases-oxygen-vs-carbon-dioxide-transport', 'neet-biology-breathing-and-exchange-of-gases', 'O2 vs CO2 Transport', 'comparison', 'The source gives distinct dominant transport modes for oxygen and carbon dioxide.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Feature","O2","CO2"],"rows":[["Major transport form","Oxyhaemoglobin","Bicarbonates"],["Minor dissolved fraction","3% in plasma","7% as carbonic acid"],["Protein-bound form","97% by haemoglobin","20-25% as carbamino-haemoglobin"],["Per 100 ml blood","Oxygenated blood delivers around 5 ml O2 to tissues","Deoxygenated blood delivers about 4 ml CO2 to alveoli"]]}'::jsonb, null, null, '{"recall_question":"Which gas is mainly transported as bicarbonates?","reveal_answer":"CO2.","key_points":[],"examples":[],"neet_traps":["O2 is mainly transported as oxyhaemoglobin."]}'::jsonb, 5, 71, 15, true),
  ('neet-biology-breathing-and-exchange-of-gases-respiration-regulation', 'neet-biology-breathing-and-exchange-of-gases', 'Regulation of Respiration', 'classification', 'Respiration is regulated mainly by centres and receptors responding to CO2 and H+.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Component","Role in source"],"rows":[["Respiratory rhythm centre","Inspiratory and expiratory centres in medulla oblongata regulate respiratory rhythms."],["Pneumotaxic centre","In pons; moderates respiratory rhythm by reducing inspiration duration and altering rate."],["Chemosensitive area","Adjacent to rhythm centre; activated by increased CO2 and H+."],["Aortic arch and carotid artery receptors","Recognize CO2 and H+ changes and send signals."],["Oxygen","Role is quite insignificant."]]}'::jsonb, null, null, '{"recall_question":"Which respiratory regulator has a quite insignificant role in the source?","reveal_answer":"Oxygen.","key_points":[],"examples":[],"neet_traps":["CO2 and H+ are the major chemical cues."]}'::jsonb, 5, 71, 16, true),
  ('neet-biology-breathing-and-exchange-of-gases-respiratory-disorders', 'neet-biology-breathing-and-exchange-of-gases', 'Respiratory Disorders', 'comparison', 'The source lists three respiratory disorders and their key cause-effect recall.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Disorder","Source-backed recall"],"rows":[["Asthma","Difficulty in breathing with wheezing due to inflammation of bronchi and bronchioles."],["Emphysema","Damage of alveolar walls decreases respiratory surface; major cause is cigarette smoking."],["Occupational respiratory disorders","Long exposure to dust can cause inflammation, fibrosis and lung damage."]]}'::jsonb, null, null, '{"recall_question":"Which disorder damages alveolar walls and decreases respiratory surface?","reveal_answer":"Emphysema.","key_points":[],"examples":[],"neet_traps":["Cigarette smoking is stated as a major cause."]}'::jsonb, 5, 71, 17, true),
  ('neet-biology-body-fluid-and-circulation-open-vs-closed-circulation', 'neet-biology-body-fluid-and-circulation', 'Open vs Closed Circulatory System', 'comparison', 'The source compares circulatory systems by vessel confinement and examples.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Feature","Open","Closed"],"rows":[["Blood path","Pumped through large vessels into open spaces or cavities called sinuses","Blood flows through blood vessels"],["Regulation","Less precise","More advantageous because flow can be precisely regulated"],["Examples","Arthropods and molluscs","Annelids and chordates"]]}'::jsonb, null, null, '{"recall_question":"Which circulatory system has blood in sinuses?","reveal_answer":"Open circulatory system.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 4, 72, 1, true),
  ('neet-biology-body-fluid-and-circulation-heart-chambers-animal-groups', 'neet-biology-body-fluid-and-circulation', 'Chambered Hearts in Vertebrates', 'classification', 'Heart chambers differ across vertebrate groups.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Group","Heart chamber pattern"],"rows":[["Fishes","2-chambered heart: an atrium and a ventricle"],["Amphibians","3-chambered heart: two atria and one ventricle"],["Reptiles except crocodiles","3-chambered heart with incompletely partitioned ventricle"],["Crocodiles, birds and mammals","4-chambered heart"]]}'::jsonb, null, null, '{"recall_question":"Which reptiles are listed with a 4-chambered heart?","reveal_answer":"Crocodiles.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 4, 72, 2, true),
  ('neet-biology-body-fluid-and-circulation-single-incomplete-double-double', 'neet-biology-body-fluid-and-circulation', 'Single, Incomplete Double and Double Circulation', 'comparison', 'The source classifies circulation by mixing and circuit pattern.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Type","Source-backed recall","Examples"],"rows":[["Single circulation","Deoxygenated blood goes heart → gills → body → heart; heart is venous","Fishes"],["Incomplete double circulation","Oxygenated and deoxygenated blood mix in a single ventricle","Amphibians and reptiles"],["Double circulation","No mixing; right side handles deoxygenated blood and left side handles oxygenated blood","Birds and mammals"]]}'::jsonb, '{"type":"bio-double-circulation"}'::jsonb, null, '{"recall_question":"Which circulation has no mixing in the source?","reveal_answer":"Double circulation.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 72, 3, true),
  ('neet-biology-body-fluid-and-circulation-plasma-composition', 'neet-biology-body-fluid-and-circulation', 'Plasma Composition', 'fact', 'Plasma forms 55% of blood and is straw-coloured, slightly alkaline and viscous.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Component","Source value/detail"],"rows":[["Plasma share","55% of blood"],["Formed elements","45% of blood"],["pH","7.4"],["Water","90-92%"],["Plasma proteins","6-8%"],["Serum","Plasma without clotting factors"]]}'::jsonb, null, null, '{"recall_question":"What is serum?","reveal_answer":"Plasma without clotting factors.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 72, 4, true),
  ('neet-biology-body-fluid-and-circulation-plasma-proteins', 'neet-biology-body-fluid-and-circulation', 'Plasma Proteins', 'comparison', 'The source assigns specific roles to the major plasma proteins.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Protein","Function"],"rows":[["Fibrinogen","Blood clotting"],["Globulins","Antibodies and defence"],["Albumins","Osmotic balance and regulation of BP"]]}'::jsonb, null, null, '{"recall_question":"Which plasma protein helps osmotic balance and BP regulation?","reveal_answer":"Albumins.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 4, 72, 5, true),
  ('neet-biology-body-fluid-and-circulation-formed-elements-comparison', 'neet-biology-body-fluid-and-circulation', 'RBC vs WBC vs Platelets', 'comparison', 'Formed elements differ in count, origin, lifespan and function.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Feature","RBC","WBC","Platelets"],"rows":[["Other name","Erythrocytes","Leucocytes","Thrombocytes"],["Key structure","Biconcave, non-nucleated, no mitochondria/Golgi etc.","Colourless and nucleated","Colourless non-nucleated cell fragments"],["Count","5-5.5 millions/mm3","6000-8000/mm3","1.5-3.5 lakhs/mm3"],["Formation","Red bone marrow","Bone marrow, lymph glands and spleen","Megakaryocytes in bone marrow"],["Lifespan","120 days","1-15 days","7 days"],["Function","CO2 and O2 transports","Immune system","Blood clotting"]]}'::jsonb, null, null, '{"recall_question":"Which formed elements are non-nucleated cell fragments?","reveal_answer":"Platelets.","key_points":[],"examples":[],"neet_traps":["Blood is treated as a fluid connective tissue in this chapter."]}'::jsonb, 5, 72, 6, true),
  ('neet-biology-body-fluid-and-circulation-rbc-haemoglobin-spleen', 'neet-biology-body-fluid-and-circulation', 'RBC Recall Values', 'fact', 'RBC facts are numerical and source-specific.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Cue","Source-backed answer"],"rows":[["Colour","Red due to haemoglobin"],["Normal Hb concentration","12-16 g/100 ml"],["RBC count","5-5.5 millions/mm3"],["Lifespan","120 days"],["Destroyed in","Spleen, called graveyard of RBCs"]]}'::jsonb, null, null, '{"recall_question":"Which organ is called the graveyard of RBCs?","reveal_answer":"Spleen.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 72, 7, true),
  ('neet-biology-body-fluid-and-circulation-wbc-types', 'neet-biology-body-fluid-and-circulation', 'WBC Type Comparison', 'comparison', 'Granulocytes and agranulocytes are compared by percentage and role.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["WBC type","Percentage","Source-backed role"],"rows":[["Neutrophils","60-65%","Soldiers of body; phagocytosis"],["Eosinophils","2-3%","Resist infections and cause allergic reactions"],["Basophils","0.5-1%","Secrete histamine, serotonin, heparin etc.; cause inflammatory reactions"],["Lymphocytes","20-25%","B and T lymphocytes; immune responses and antibodies"],["Monocytes","6-8%","Largest WBC; phagocytosis"]]}'::jsonb, null, null, '{"recall_question":"Which WBC is largest in the source?","reveal_answer":"Monocytes.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 72, 8, true),
  ('neet-biology-body-fluid-and-circulation-coagulation-flow', 'neet-biology-body-fluid-and-circulation', 'Blood Coagulation Flow', 'process', 'The source gives clotting as an enzyme conversion sequence ending in fibrin clot.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Step","Event"],"rows":[["1","Clumped platelets and tissues release thromboplastin"],["2","Thromboplastin forms thrombokinase or prothrombinase"],["3","Thrombokinase hydrolyses prothrombin to thrombin in presence of Ca2+"],["4","Thrombin converts soluble fibrinogen into insoluble fibrin"],["5","Fibrin threads trap damaged blood cells and form clot or coagulum"]]}'::jsonb, null, null, '{"recall_question":"Which ion is required for prothrombin to thrombin conversion in the source?","reveal_answer":"Ca2+.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 4, 72, 9, true),
  ('neet-biology-body-fluid-and-circulation-abo-blood-groups', 'neet-biology-body-fluid-and-circulation', 'ABO Blood Group Table', 'table', 'ABO grouping is based on antigens on RBCs and antibodies in plasma.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Group","Antigen","Antibody","Donates to","Receives from"],"rows":[["A","A","Anti-B","A, AB","A, O"],["B","B","Anti-A","B, AB","B, O"],["AB","A, B","Nil","AB only","A, B, AB, O"],["O","Nil","Anti-A, Anti-B","A, B, AB, O","O only"]]}'::jsonb, null, null, '{"recall_question":"Which ABO group is the universal recipient in the source?","reveal_answer":"AB.","key_points":["O is the universal donor."],"examples":[],"neet_traps":[]}'::jsonb, 5, 73, 10, true),
  ('neet-biology-body-fluid-and-circulation-abo-neet-trap', 'neet-biology-body-fluid-and-circulation', 'ABO Antigen-Antibody Trap', 'neet_trap', 'Agglutination occurs when interacting antigens and antibodies are mixed.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["RBC antigen","Plasma antibody that reacts"],"rows":[["A","Anti-A"],["B","Anti-B"]]}'::jsonb, null, null, '{"recall_question":"What causes agglutination in ABO transfusion?","reveal_answer":"Interaction between matching RBC antigens and plasma antibodies.","key_points":[],"examples":[],"neet_traps":["Do not pair group A with anti-B for agglutination; antigen A reacts with anti-A."]}'::jsonb, 5, 73, 11, true),
  ('neet-biology-body-fluid-and-circulation-rh-factor', 'neet-biology-body-fluid-and-circulation', 'Rh Factor and Erythroblastosis Foetalis', 'concept', 'Rh factor is an RBC antigen; Rh incompatibility can harm later Rh+ foetuses of an Rh- mother.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Cue","Source-backed detail"],"rows":[["Rh+ve","Rh antigen present on RBCs"],["Rh-ve","Rh antigen absent"],["Frequency","Nearly 80% humans are Rh+ve"],["Anti-Rh antibodies","Not naturally found"],["Prevention","Anti-Rh antibodies to mother immediately after first delivery"]]}'::jsonb, null, null, '{"recall_question":"Why is Rh matching needed before transfusion?","reveal_answer":"An Rh-ve person can develop anti-Rh antibodies after receiving Rh+ blood, causing agglutination on later exposure.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 73, 12, true),
  ('neet-biology-body-fluid-and-circulation-artery-vs-vein', 'neet-biology-body-fluid-and-circulation', 'Artery vs Vein', 'comparison', 'Blood vessels are named by direction relative to the heart, not by oxygenation.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Feature","Artery","Vein"],"rows":[["Direction","Carry blood from heart to tissues","Carry blood to heart"],["Usual oxygenation","Oxygenated","Deoxygenated"],["Exception","Pulmonary artery is deoxygenated","Pulmonary vein is oxygenated"],["Smaller branches","Arterioles","Venules"],["Wall","Three layers; tunica media stronger","Three-layered but tunica media comparatively thin"]]}'::jsonb, null, null, '{"recall_question":"Which artery carries deoxygenated blood?","reveal_answer":"Pulmonary artery.","key_points":[],"examples":[],"neet_traps":["Arteries and veins are defined by direction, not oxygen level."]}'::jsonb, 5, 73, 13, true),
  ('neet-biology-body-fluid-and-circulation-heart-anatomy', 'neet-biology-body-fluid-and-circulation', 'Human Heart Anatomy', 'classification', 'The source describes the human heart as a four-chambered mesodermal organ in the mediastinum.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Structure","Source-backed detail"],"rows":[["Pericardium","Double layered; pericardial fluid reduces friction"],["Septa","Inter-atrial and inter-ventricular septa separate chambers"],["Tricuspid valve","Between right atrium and right ventricle"],["Bicuspid/mitral valve","Between left atrium and left ventricle"],["Semilunar valves","At openings of pulmonary artery and aorta; prevent backflow"]]}'::jsonb, null, null, '{"recall_question":"Which valve lies between left atrium and left ventricle?","reveal_answer":"Bicuspid or mitral valve.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 73, 14, true),
  ('neet-biology-body-fluid-and-circulation-heart-blood-flow', 'neet-biology-body-fluid-and-circulation', 'Heart Blood-Flow Route', 'sequence', 'Blood flow through the heart is one-way because of valves.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Side","Route"],"rows":[["Right side","Vena cava → Right atrium → Tricuspid valve → Right ventricle → Pulmonary artery"],["Left side","Pulmonary veins → Left atrium → Bicuspid/mitral valve → Left ventricle → Aorta"]]}'::jsonb, '{"type":"bio-heart-flow"}'::jsonb, null, '{"recall_question":"Which major vessel leaves the right ventricle?","reveal_answer":"Pulmonary artery.","key_points":[],"examples":[],"neet_traps":["Pulmonary artery carries deoxygenated blood."]}'::jsonb, 5, 73, 15, true),
  ('neet-biology-body-fluid-and-circulation-conducting-system', 'neet-biology-body-fluid-and-circulation', 'Cardiac Conducting System', 'sequence', 'Nodal tissue generates and conducts impulses through the heart.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Part","Source-backed recall"],"rows":[["SAN","Right upper corner of right atrium; initiates and maintains contraction"],["AVN","Lower left corner of right atrium close to AV septum"],["AV bundle","Passes through AV septa and divides into right and left branches"],["Purkinje fibres","Fine fibres through ventricular musculature"],["Pacemaker","SAN, with 70-75 action potentials/min"]]}'::jsonb, '{"type":"bio-cardiac-conduction"}'::jsonb, null, '{"recall_question":"What is the natural pacemaker of the human heart?","reveal_answer":"SA node.","key_points":["It initiates and maintains contraction with 70-75 action potentials/min."],"examples":[],"neet_traps":[]}'::jsonb, 5, 73, 16, true),
  ('neet-biology-body-fluid-and-circulation-cardiac-cycle', 'neet-biology-body-fluid-and-circulation', 'Cardiac Cycle', 'process', 'One heartbeat is one cardiac cycle and takes 0.8 seconds in the source.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Stage","Valve state / event"],"rows":[["Joint diastole","All chambers relaxed; tricuspid and bicuspid valves open; semilunar valves closed"],["Atrial systole","SAN action potential contracts atria; flow into ventricles increases about 30%"],["Ventricular systole","AVN/AV bundle conduct impulse; AV valves close; semilunar valves open"],["Ventricular diastole","Ventricles relax; semilunar valves close; AV valves open by atrial pressure"]]}'::jsonb, null, null, '{"recall_question":"How long is one cardiac cycle in the source?","reveal_answer":"0.8 seconds.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 74, 17, true),
  ('neet-biology-body-fluid-and-circulation-heart-sounds-output', 'neet-biology-body-fluid-and-circulation', 'Heart Sounds and Cardiac Output', 'fact', 'The source gives the standard heart rate, stroke volume and cardiac output.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Cue","Source-backed answer"],"rows":[["Normal heartbeat","70-75/min, average 72/min"],["Stroke volume","About 70 ml"],["Cardiac output","Stroke volume × heart rate = 70 × 72 = about 5000 ml or 5 litres"],["Lub","Closure of tricuspid and bicuspid valves"],["Dub","Closure of semilunar valves"]]}'::jsonb, null, null, '{"recall_question":"What causes the lub sound?","reveal_answer":"Closure of tricuspid and bicuspid valves.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 74, 18, true),
  ('neet-biology-body-fluid-and-circulation-ecg-waves', 'neet-biology-body-fluid-and-circulation', 'ECG Waves', 'classification', 'An electrocardiogram represents electrical activity during the cardiac cycle.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Wave/complex","Source-backed meaning"],"rows":[["P wave","Excitation or depolarization of atria during atrial systole"],["QRS complex","Depolarization of ventricles during ventricular systole"],["T wave","Repolarisation of ventricles"]]}'::jsonb, '{"type":"bio-ecg"}'::jsonb, null, '{"recall_question":"Which ECG part represents ventricular depolarization?","reveal_answer":"QRS complex.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 74, 19, true),
  ('neet-biology-body-fluid-and-circulation-pulmonary-vs-systemic', 'neet-biology-body-fluid-and-circulation', 'Pulmonary vs Systemic Circulation', 'comparison', 'Double circulation separates lung and body circuits.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Feature","Pulmonary circulation","Systemic circulation"],"rows":[["Start","Right ventricle","Left ventricle"],["Route","Pulmonary artery → lungs → pulmonary veins","Aorta → arteries → arterioles → capillaries → venules → veins → vena cava"],["End","Left atrium","Right atrium"],["Function","Oxygenates blood","Provides nutrients/O2 and removes CO2/harmful substances"]]}'::jsonb, null, null, '{"recall_question":"Where does pulmonary circulation end?","reveal_answer":"Left atrium.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 74, 20, true),
  ('neet-biology-body-fluid-and-circulation-portal-coronary-circulation', 'neet-biology-body-fluid-and-circulation', 'Portal and Coronary Circulation', 'fact', 'The source names two special circulations.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Circulation","Source-backed recall"],"rows":[["Hepatic portal system","Hepatic portal vein carries blood from intestine to liver before systemic circulation."],["Coronary circulation","Coronary vessels circulate blood to and from cardiac musculature."]]}'::jsonb, null, null, '{"recall_question":"Which vessel carries blood from intestine to liver before systemic circulation?","reveal_answer":"Hepatic portal vein.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 4, 74, 21, true),
  ('neet-biology-body-fluid-and-circulation-cardiac-regulation', 'neet-biology-body-fluid-and-circulation', 'Regulation of Cardiac Activity', 'comparison', 'The heart is myogenic, with regulation by ANS and adrenal medullary hormones.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Regulator","Source-backed effect"],"rows":[["Nodal tissues","Auto-regulate the myogenic heart"],["Sympathetic nerves","Increase heartbeat rate, strength of ventricular contraction and cardiac output"],["Parasympathetic nerves","Decrease heartbeat, conduction and cardiac output"],["Adrenal medullary hormones","Increase cardiac output"]]}'::jsonb, null, null, '{"recall_question":"What does sympathetic stimulation do to cardiac output?","reveal_answer":"Increases cardiac output.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 4, 75, 22, true),
  ('neet-biology-body-fluid-and-circulation-lymph', 'neet-biology-body-fluid-and-circulation', 'Lymph and Lymphatic System', 'concept', 'Lymph is tissue fluid that enters lymphatic vessels and drains into major veins.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Cue","Source-backed detail"],"rows":[["Composition","Colourless fluid with same mineral distribution as plasma; contains lymphocytes"],["Exchange role","Middleman between blood and tissues for nutrients and gases"],["Transport role","Carries liver plasma proteins to blood; transports digested fats, fat soluble vitamins and hormones"],["Defence role","Filters bacteria and foreign particles; lymph nodes produce WBC and antibodies"]]}'::jsonb, null, null, '{"recall_question":"Which lymph vessels transport digested fats?","reveal_answer":"Lacteals.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 75, 23, true),
  ('neet-biology-body-fluid-and-circulation-circulatory-disorders', 'neet-biology-body-fluid-and-circulation', 'Circulatory Disorders', 'comparison', 'The source distinguishes blood pressure, coronary artery disease and heart failure terms.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Disorder","Source-backed recall"],"rows":[["Hypertension","Repeated BP of 140/90 or above; normal BP is 120/80 mm Hg"],["CAD/atherosclerosis","Calcium, fat, cholesterol and fibrous tissue deposited in coronary arteries, narrowing lumen"],["Angina","Acute chest pain due to O2 deficiency to heart muscles from improper blood flow"],["Heart failure","Inability to pump enough blood; lung congestion is main symptom"],["Cardiac arrest","Heart stops beating"],["Heart attack","Sudden damage of heart muscle due to inadequate blood supply"]]}'::jsonb, null, null, '{"recall_question":"What BP value shows hypertension in the source?","reveal_answer":"Repeated blood pressure of 140/90 or above.","key_points":["Normal BP is 120/80 mm Hg."],"examples":[],"neet_traps":[]}'::jsonb, 5, 75, 24, true),
  ('neet-biology-excretory-products-and-their-elimination-ammonotelic-ureotelic-uricotelic', 'neet-biology-excretory-products-and-their-elimination', 'Ammonotelic vs Ureotelic vs Uricotelic', 'comparison', 'Nitrogenous wastes differ in toxicity, water need and animal examples.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Type","Waste","Water/toxicity recall","Source examples"],"rows":[["Ammonotelism","NH3","Highly toxic, soluble, needs excess water","Aquatic invertebrates, aquatic insects, bony fishes, aquatic amphibians etc."],["Ureotelism","Urea","Less toxic; moderate water","Cartilaginous fishes, frogs, toads, alligators, turtles, mammals etc."],["Uricotelism","Uric acid","Water insoluble, less toxic; no water needed","Insects, some land crustaceans, land snails, terrestrial reptiles and birds"]]}'::jsonb, null, null, '{"recall_question":"Which nitrogenous waste needs excess water for excretion?","reveal_answer":"Ammonia or NH3.","key_points":[],"examples":[],"neet_traps":["Ureotelism and uricotelism help in water conservation."]}'::jsonb, 5, 76, 1, true),
  ('neet-biology-excretory-products-and-their-elimination-excretory-organs-examples', 'neet-biology-excretory-products-and-their-elimination', 'Excretory Organs Across Animals', 'examples', 'The source lists animal groups with their excretory organs.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Organ","Source examples / role"],"rows":[["Protonephridia or flame cells","Flatworms, rotifers, some annelids and Amphioxus; primarily osmoregulation"],["Nephridia","Annelids; nitrogenous wastes and osmoregulation"],["Malpighian tubules","Insects; nitrogenous wastes and osmoregulation"],["Antennal or green glands","Crustaceans such as prawn"],["Kidneys","Higher animals"]]}'::jsonb, null, null, '{"recall_question":"What are the excretory organs of insects in the source?","reveal_answer":"Malpighian tubules.","key_points":[],"examples":[],"neet_traps":["They also help in osmoregulation."]}'::jsonb, 5, 76, 2, true),
  ('neet-biology-excretory-products-and-their-elimination-human-urinary-system', 'neet-biology-excretory-products-and-their-elimination', 'Human Urinary System', 'classification', 'The human excretory system consists of kidneys, ureters, urinary bladder and urethra.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Part","Recall cue"],"rows":[["Kidneys","Paired reddish brown bean-shaped organs"],["Ureters","Carry urine from kidneys"],["Urinary bladder","Stores urine"],["Urethra","Passage for urine out of the body"]]}'::jsonb, '{"type":"bio-urinary-system"}'::jsonb, null, '{"recall_question":"Name the four parts of the human excretory system.","reveal_answer":"Kidneys, ureters, urinary bladder and urethra.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 4, 76, 3, true),
  ('neet-biology-excretory-products-and-their-elimination-kidney-structure-values', 'neet-biology-excretory-products-and-their-elimination', 'Kidney Structure and Values', 'fact', 'Kidney size and structure values are source-specific.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Cue","Source-backed answer"],"rows":[["Position","Between last thoracic and 3rd lumbar vertebra"],["Size","10-12 cm long, 5-7 cm wide, 2-3 cm thick"],["Weight","Average 120-170 gm"],["Capsule","Tough 3-layer fibrous renal capsule"],["Hilum","Concave entry/exit for blood vessels, nerves, lymphatic ducts and ureter"],["Nephrons","Nearly one million tubular nephrons in each kidney"]]}'::jsonb, null, null, '{"recall_question":"How many nephrons are present in each kidney according to the source?","reveal_answer":"Nearly one million.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 76, 4, true),
  ('neet-biology-excretory-products-and-their-elimination-cortex-medulla-pyramids', 'neet-biology-excretory-products-and-their-elimination', 'Cortex, Medulla and Pyramids', 'classification', 'The kidney has an outer cortex and inner medulla.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Region","Source-backed detail"],"rows":[["Cortex","Outer region; extends between medullary pyramids as renal columns or Columns of Bertini"],["Medulla","Inner region with medullary or renal pyramids"],["Pyramids","Project into calyces"],["Renal pelvis","Hilum leads into renal pelvis with calyces"]]}'::jsonb, null, null, '{"recall_question":"What are Columns of Bertini?","reveal_answer":"Cortical extensions between medullary pyramids.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 4, 76, 5, true),
  ('neet-biology-excretory-products-and-their-elimination-nephron-structure', 'neet-biology-excretory-products-and-their-elimination', 'Nephron Structure', 'classification', 'The nephron is the structural and functional unit of kidney.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Part","Source-backed recall"],"rows":[["Glomerulus","Tuft of capillaries formed by afferent arteriole; blood leaves by efferent arteriole"],["Bowman''s capsule","Encloses glomerulus"],["Malpighian body","Glomerulus + Bowman''s capsule"],["Tubule order","PCT → Henle''s loop → DCT → collecting duct"],["Vasa recta","U-shaped minute vessel parallel to Henle''s loop"]]}'::jsonb, '{"type":"bio-nephron-flow"}'::jsonb, null, '{"recall_question":"What forms the Malpighian body?","reveal_answer":"Glomerulus and Bowman''s capsule.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 76, 6, true),
  ('neet-biology-excretory-products-and-their-elimination-cortical-vs-juxtamedullary-nephron', 'neet-biology-excretory-products-and-their-elimination', 'Cortical vs Juxtamedullary Nephron', 'comparison', 'The source gives both percentage and loop/vasa recta differences.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Feature","Cortical nephron","Juxtamedullary nephron"],"rows":[["Percentage","85%","15%"],["Henle''s loop","Short; extends little into medulla","Long; extends deep into medulla"],["Vasa recta","Absent or reduced","Present"]]}'::jsonb, null, null, '{"recall_question":"Which nephron type has a long loop of Henle and vasa recta?","reveal_answer":"Juxtamedullary nephron.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 76, 7, true),
  ('neet-biology-excretory-products-and-their-elimination-urine-formation-overview', 'neet-biology-excretory-products-and-their-elimination', 'Urine Formation Overview', 'sequence', 'Urine formation has three source-listed processes.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Order","Process"],"rows":[["1","Glomerular filtration or ultrafiltration"],["2","Selective reabsorption"],["3","Tubular secretion"]]}'::jsonb, null, null, '{"recall_question":"What are the three processes of urine formation?","reveal_answer":"Filtration, reabsorption and secretion.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 77, 8, true),
  ('neet-biology-excretory-products-and-their-elimination-glomerular-filtration', 'neet-biology-excretory-products-and-their-elimination', 'Glomerular Filtration', 'process', 'Blood pressure filters plasma through a three-layer filtration membrane into Bowman''s capsule.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Cue","Source-backed detail"],"rows":[["Filtration layers","Endothelium of glomerular vessels, epithelium of Bowman''s capsule and basement membrane"],["Podocytes","Leave filtration slits or slit pores"],["Filtered material","Almost all plasma except proteins"],["Blood filtered","1100-1200 ml per minute"],["GFR","125 ml/min or 180 litres/day"]]}'::jsonb, null, null, '{"recall_question":"What is normal GFR in the source?","reveal_answer":"125 ml/min or 180 litres/day.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 77, 9, true),
  ('neet-biology-excretory-products-and-their-elimination-reabsorption-values', 'neet-biology-excretory-products-and-their-elimination', 'Selective Reabsorption Values', 'fact', 'Most filtrate is reabsorbed; only a small volume becomes urine.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Cue","Source-backed value/detail"],"rows":[["Filtrate per day","180 litres"],["Reabsorbed","99%"],["Normal urine","1.5 litres"],["Active reabsorption","Glucose, amino acids, Na+"],["Passive reabsorption","Nitrogenous wastes and water in initial segments"]]}'::jsonb, null, null, '{"recall_question":"How much filtrate is reabsorbed according to the source?","reveal_answer":"99%.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 77, 10, true),
  ('neet-biology-excretory-products-and-their-elimination-pct-loop-dct-collecting-duct', 'neet-biology-excretory-products-and-their-elimination', 'PCT vs Loop vs DCT vs Collecting Duct', 'comparison', 'Tubular parts differ in permeability and reabsorption roles.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Part","Source-backed role"],"rows":[["PCT","Reabsorbs most nutrients and 70-80% electrolytes and water; brush border cuboidal epithelium"],["Descending limb","Permeable to water, almost impermeable to electrolytes"],["Ascending limb","Impermeable to water, transports electrolytes, dilutes filtrate"],["DCT","Conditional reabsorption of Na+ and water"],["Collecting duct","Reabsorbs large water, concentrates urine and allows small urea into medullary interstitium"]]}'::jsonb, null, null, '{"recall_question":"Which nephron part reabsorbs 70-80% electrolytes and water?","reveal_answer":"PCT.","key_points":[],"examples":[],"neet_traps":["PCT has simple cuboidal brush border epithelium."]}'::jsonb, 5, 77, 11, true),
  ('neet-biology-excretory-products-and-their-elimination-filtration-reabsorption-secretion', 'neet-biology-excretory-products-and-their-elimination', 'Filtration vs Reabsorption vs Secretion', 'comparison', 'The three urine-formation processes move materials in different directions.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Process","Direction / role"],"rows":[["Filtration","Blood plasma except proteins passes into Bowman''s capsule"],["Reabsorption","Useful substances and water move from filtrate back to blood"],["Secretion","H+, K+ and NH3 are secreted to maintain ionic and acid-base balance"]]}'::jsonb, null, null, '{"recall_question":"Which urine-formation process maintains acid-base balance by H+, K+ and NH3 secretion?","reveal_answer":"Tubular secretion.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 77, 12, true),
  ('neet-biology-excretory-products-and-their-elimination-counter-current-mechanism', 'neet-biology-excretory-products-and-their-elimination', 'Counter-Current Mechanism', 'process', 'Henle''s loop and vasa recta create and preserve the medullary gradient for concentrated urine.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Cue","Source-backed detail"],"rows":[["Counter-current","Filtrate in Henle limbs and blood in vasa recta flow in opposite directions"],["Gradient","Cortex 300 mOsmolL-1 to inner medulla 1200 mOsmolL-1"],["Gradient substances","NaCl and urea"],["NaCl route","Transported by ascending limb, exchanged with descending vasa recta, returned by ascending vasa recta"],["Final concentration","DCT and collecting duct produce urine four times concentrated than initial filtrate"]]}'::jsonb, '{"type":"bio-counter-current"}'::jsonb, null, '{"recall_question":"Which two structures form the counter-current mechanism?","reveal_answer":"Henle''s loop and vasa recta.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 77, 13, true),
  ('neet-biology-excretory-products-and-their-elimination-micturition', 'neet-biology-excretory-products-and-their-elimination', 'Micturition Reflex', 'process', 'Micturition is a neural reflex triggered by bladder stretch.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Step","Event"],"rows":[["1","Urinary bladder fills and stretches"],["2","Stretch receptors send impulses to CNS"],["3","CNS sends motor messages"],["4","Bladder smooth muscles contract"],["5","Urethral sphincter relaxes and urine is released"]]}'::jsonb, null, null, '{"recall_question":"What triggers the micturition reflex?","reveal_answer":"Stretching of the urinary bladder.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 4, 77, 14, true),
  ('neet-biology-excretory-products-and-their-elimination-urine-values', 'neet-biology-excretory-products-and-their-elimination', 'Urine Values', 'fact', 'The source gives daily urine and urea values plus urine pH.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Cue","Source value"],"rows":[["Adult urine","1 to 1.5 litres/day"],["Urea","25-30 gm/day"],["Urine pH","Slightly acidic pH 6.0"],["Lung excretion","CO2 at 200 mL/minute plus water"]]}'::jsonb, null, null, '{"recall_question":"What is the urine pH stated in the source?","reveal_answer":"Slightly acidic pH 6.0.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 77, 15, true),
  ('neet-biology-excretory-products-and-their-elimination-other-excretory-organs-human', 'neet-biology-excretory-products-and-their-elimination', 'Other Human Excretory Organs', 'classification', 'Besides kidneys, lungs, liver, skin and saliva eliminate wastes.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Organ","Excretory role"],"rows":[["Lungs","Remove CO2 and water"],["Liver","Bile contains bilirubin, biliverdin, cholesterol, degraded steroid hormones, vitamins and drugs"],["Sweat glands","Remove water, NaCl, urea and lactic acid; cooling effect"],["Sebaceous glands","Eliminate sterols, hydrocarbons and waxes through sebum"],["Saliva","Eliminates small nitrogenous wastes"]]}'::jsonb, null, null, '{"recall_question":"Which skin secretion gives a protective oily covering?","reveal_answer":"Sebum.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 4, 78, 16, true),
  ('neet-biology-excretory-products-and-their-elimination-adh-regulation', 'neet-biology-excretory-products-and-their-elimination', 'ADH Regulation of Kidney Function', 'process', 'ADH is released when osmoreceptors detect decreased body fluid volume.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Step","Source-backed event"],"rows":[["1","Decrease in body fluid activates osmoreceptors"],["2","Hypothalamus releases ADH or vasopressin"],["3","ADH stimulates water reabsorption from DCT and collecting duct"],["4","Diuresis is prevented and body fluid volume increases"],["5","ADH also constricts blood vessels, increasing BP, glomerular blood flow and GFR"]]}'::jsonb, null, null, '{"recall_question":"Where does ADH increase water reabsorption in the source?","reveal_answer":"DCT and collecting duct.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 78, 17, true),
  ('neet-biology-excretory-products-and-their-elimination-jga-raas-anf', 'neet-biology-excretory-products-and-their-elimination', 'JGA, RAAS and ANF', 'process', 'JGA responds to reduced glomerular flow/pressure/GFR; ANF checks the renin-angiotensin mechanism.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Regulator","Source-backed role"],"rows":[["JGA","Cellular modification of DCT and afferent arteriole at contact; regulates GFR"],["Renin","Released by JG cells when glomerular blood flow, pressure or GFR falls"],["Angiotensin II","Vasoconstrictor; increases glomerular BP/GFR and activates aldosterone release"],["Aldosterone","Causes reabsorption of Na+ and water from distal tubule"],["ANF","Released by atria when blood flow increases; causes vasodilation and decreases BP"]]}'::jsonb, null, null, '{"recall_question":"Which factor checks the renin-angiotensin mechanism?","reveal_answer":"Atrial Natriuretic Factor (ANF).","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 78, 18, true),
  ('neet-biology-excretory-products-and-their-elimination-excretory-disorders', 'neet-biology-excretory-products-and-their-elimination', 'Excretory Disorders', 'comparison', 'The source lists kidney disorders and treatment.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Condition","Source-backed recall"],"rows":[["Uremia","Accumulation of urea in blood due kidney malfunction; may lead renal failure"],["Renal calculi","Stone or insoluble crystallized salts such as oxalates in kidney"],["Glomerulonephritis","Inflammation of glomeruli"],["Hemodialysis","Removal of urea using a dialyzing unit or artificial kidney"],["Kidney transplantation","Ultimate method for acute renal failures; close relative minimizes rejection chance"]]}'::jsonb, null, null, '{"recall_question":"What is uremia?","reveal_answer":"Accumulation of urea in blood due to kidney malfunction.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 78, 19, true),
  ('neet-biology-excretory-products-and-their-elimination-hemodialysis-flow', 'neet-biology-excretory-products-and-their-elimination', 'Hemodialysis Flow', 'sequence', 'The source describes hemodialysis as diffusion of nitrogenous wastes across a porous membrane.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Step","Event"],"rows":[["1","Blood is drained from an artery"],["2","Heparin is added and blood is pumped into dialyzing unit"],["3","Blood flows through coiled cellophane tube surrounded by dialyzing fluid"],["4","Dialyzing fluid has plasma-like composition except nitrogenous wastes"],["5","Nitrogenous wastes move out by concentration gradient"],["6","Purified blood returns through a vein after anti-heparin"]]}'::jsonb, null, null, '{"recall_question":"Why do nitrogenous wastes move out during hemodialysis?","reveal_answer":"The dialyzing fluid lacks nitrogenous wastes, creating a concentration gradient.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 4, 78, 20, true),
  ('neet-biology-locomotion-and-movement-locomotion-vs-movement', 'neet-biology-locomotion-and-movement', 'Locomotion vs Movement', 'concept', 'Locomotion is voluntary movement resulting in change in location.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Recall cue","Source detail"],"rows":[["Core distinction","All locomotion are movements but all movements are not locomotion."],["Paramoecium","Cilia help in movement of food through cytopharynx and in locomotion."],["Hydra","Tentacles capture prey and help in locomotion."],["Limbs","Help change body postures and help locomotion."]]}'::jsonb, null, null, '{"recall_question":"Are all movements locomotion?","reveal_answer":"No. All locomotion are movements, but all movements are not locomotion.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 79, 1, true),
  ('neet-biology-locomotion-and-movement-types-of-movement', 'neet-biology-locomotion-and-movement', 'Types of Movement', 'classification', 'The source lists amoeboid, ciliary, muscular and flagellar movement.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Movement","Mechanism","Source examples"],"rows":[["Amoeboid","Pseudopodia formed by streaming of protoplasm; microfilaments help","Amoeba, macrophages and leucocytes"],["Ciliary","By cilia","Trachea removes dust/foreign substances; oviducts move ova"],["Muscular","By muscles","Movement of limbs"],["Flagellar","By flagella","Spermatozoa, sponge canal system water current, Euglena"]]}'::jsonb, null, null, '{"recall_question":"Which movement type is used by macrophages and leucocytes?","reveal_answer":"Amoeboid movement.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 79, 2, true),
  ('neet-biology-locomotion-and-movement-muscle-properties', 'neet-biology-locomotion-and-movement', 'Human Muscular System', 'fact', 'Muscles are mesodermal in origin and constitute 40-50% of body weight.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Property","Source-backed recall"],"rows":[["Origin","Mesodermal"],["Body weight","40-50%"],["Properties","Excitability, contractility, extensibility and elasticity"]]}'::jsonb, null, null, '{"recall_question":"What percentage of body weight is muscle in the source?","reveal_answer":"40-50%.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 4, 79, 3, true),
  ('neet-biology-locomotion-and-movement-skeletal-smooth-cardiac', 'neet-biology-locomotion-and-movement', 'Skeletal vs Visceral vs Cardiac Muscle', 'comparison', 'Muscles are classified by location, striation, control and fatigue.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Feature","Skeletal","Visceral","Cardiac"],"rows":[["Location","Attached to skeleton","In visceral organs","In heart wall"],["Striations","Present","Absent","Present"],["Control","Voluntary","Involuntary","Involuntary"],["Blood supply","Rich","Poor","Rich"],["Fatigue","Fatigue muscle","Non-fatigue","Non-fatigue"],["Nuclei","Multinucleate","Uninucleate","Uninucleate"],["Mitochondria","More","Less","More"]]}'::jsonb, null, null, '{"recall_question":"Which striated muscle is involuntary?","reveal_answer":"Cardiac muscle.","key_points":[],"examples":[],"neet_traps":["Cardiac muscle is involuntary and non-fatigue in the source."]}'::jsonb, 5, 79, 4, true),
  ('neet-biology-locomotion-and-movement-striated-muscle-structure', 'neet-biology-locomotion-and-movement', 'Structure of Striated Muscle', 'classification', 'Skeletal muscle is organized from fascicles to myofibrils.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Level","Source-backed recall"],"rows":[["Muscle","Made of muscle bundles or fascicles held by fascia"],["Fascicle","Contains many muscle fibres"],["Muscle fibre","Lined by sarcolemma enclosing sarcoplasm"],["Myofibrils","Myofilaments inside muscle fibre"],["Sarcomere","Region between two Z-lines; functional unit of muscle contraction"]]}'::jsonb, null, null, '{"recall_question":"What is the functional unit of muscle contraction?","reveal_answer":"Sarcomere.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 79, 5, true),
