  ('neet-biology-locomotion-and-movement-actin-vs-myosin', 'neet-biology-locomotion-and-movement', 'Actin vs Myosin Filaments', 'comparison', 'The source details the protein composition of thin and thick filaments.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Feature","Actin filament","Myosin filament"],"rows":[["Main polymer","Two F-actins forming a double helix","Many meromyosins"],["Monomer","G-actin","Meromyosin"],["Associated proteins","Tropomyosin and troponin","HMM/cross arm and LMM tail"],["Resting state","Troponin subunit masks binding sites for myosin","Globular head has ATPase activity, ATP binding and actin active sites"]]}'::jsonb, null, null, '{"recall_question":"Which protein masks myosin binding sites on actin at rest?","reveal_answer":"Troponin subunit.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 79, 7, true),
  ('neet-biology-locomotion-and-movement-sliding-filament-sequence', 'neet-biology-locomotion-and-movement', 'Sliding Filament Mechanism', 'sequence', 'Muscle contraction occurs by sliding of thin filaments over thick filaments.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Step","Source-backed event"],"rows":[["1","Impulse from CNS reaches neuromuscular junction via motor neuron"],["2","Acetylcholine generates action potential in sarcolemma"],["3","Ca2+ is released from sarcoplasmic cisternae into sarcoplasm"],["4","Ca binds troponin and unmasks myosin active sites on actin"],["5","Myosin head uses ATP hydrolysis energy to form cross bridge"],["6","Actin is pulled toward centre of A-band; sarcomere shortens"],["7","New ATP breaks cross bridge; cycle repeats"],["8","Ca2+ is pumped back and relaxation occurs"]]}'::jsonb, '{"type":"bio-sliding-filament"}'::jsonb, null, '{"recall_question":"What exposes myosin binding sites during muscle contraction?","reveal_answer":"Ca2+ binding to troponin.","key_points":["This unmasks active sites on actin."],"examples":[],"neet_traps":[]}'::jsonb, 5, 80, 8, true),
